"use client";

import { useEffect } from "react";
import { SERVICE_WORKER_SCRIPT_PATH } from "@/lib/constants/browserStorageKeys";

// Registers the offline service worker (public/sw.js, generated by scripts/generateServiceWorkerShell.mjs).
// Production builds only, so development hot reload is not affected.
export function ServiceWorkerRegister() {
  useEffect(() => {
    if (process.env.NODE_ENV === "production" && "serviceWorker" in navigator) {
      navigator.serviceWorker.register(SERVICE_WORKER_SCRIPT_PATH).catch(() => undefined);
    }
  }, []);
  return null;
}
